import {wrap, shadow, ref, text} from '../style.mjs';

const r2 = v => Math.round(v * 100) / 100;
// Catmull-Rom through the points, as cubic Beziers.
function smooth(pts) {
  let d = `M${r2(pts[0][0])} ${r2(pts[0][1])}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${r2(c1[0])} ${r2(c1[1])} ${r2(c2[0])} ${r2(c2[1])} ${r2(p2[0])} ${r2(p2[1])}`;
  }
  return d;
}
// One half-profile [halfWidth, y], mirrored about x=100.
function mirrored(half) {
  const right = half.map(([h, y]) => [100 + h, y]);
  const left = half.slice().reverse().map(([h, y]) => [100 - h, y]);
  return `${smooth(right)}L${smooth(left).slice(1)}Z`;
}
const mirrorX = d => `<g transform="translate(200 0) scale(-1 1)">${d}</g>`;

